            {copied ? <span style={{ color: 'green' }}>Copied!</span> : null}
        </div>
    );
};

export default CopyTextComponent;
```

### Explanation

1. **`handleCopy` Function**: This function is called when the text is copied. It sets the `copied` state to `true` and uses `setTimeout` to reset the `copied` state to `false` after 5 seconds.
2. **`CopyToClipboard` Component**: The `onCopy` prop is set to the `handleCopy` function.

### Full Example

Here's the complete component with the timer logic to reset the `copied` state:

```javascript
import React, { useState } from 'react';
import { CopyToClipboard } from 'react-copy-to-clipboard';

const CopyTextComponent = () => {
    const [copied, setCopied] = useState(false);
    const textToCopy = "This is the text to copy";

    const handleCopy = () => {
        setCopied(true);
        setTimeout(() => {
            setCopied(false);
        }, 5000); // 5000 milliseconds = 5 seconds
    };

    return (
        <div>
            <span>{textToCopy}</span>
            <CopyToClipboard text={textToCopy} onCopy={handleCopy}>
                <button>Copy to Clipboard</button>
            </CopyToClipboard>
            {copied ? <span style={{ color: 'green' }}>Copied!</span> : null}
        </div>
    );
};

export default CopyTextComponent;
```

### Usage

To use this component, simply import it and include it in your JSX:

```javascript
import React from 'react';
import CopyTextComponent from './CopyTextComponent';

const App = () => (
    <div>
        <h1>Copy to Clipboard Example</h1>
        <CopyTextComponent />
    </div>
);

export default App;
```

