Here's a simple example of a React.js frontend application with a Node.js backend using Express and MongoDB to save words, their meanings, and IDs of synonyms:

### Frontend (React.js):

1. Create a new React.js app:
```bash
npx create-react-app synonym-manager
cd synonym-manager
```

2. Install Axios for making HTTP requests:
```bash
npm install axios
```

3. Create a component for adding words and their meanings (`WordForm.js`):

```jsx
import React, { useState } from 'react';
import axios from 'axios';

const WordForm = () => {
  const [word, setWord] = useState('');
  const [meaning, setMeaning] = useState('');
  const [synonyms, setSynonyms] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await axios.post('http://localhost:5000/words', {
        word,
        meaning,
        synonyms: synonyms.split(',').map(synonym => synonym.trim())
      });
      console.log(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" placeholder="Word" value={word} onChange={(e) => setWord(e.target.value)} required />
      <input type="text" placeholder="Meaning" value={meaning} onChange={(e) => setMeaning(e.target.value)} required />
      <input type="text" placeholder="Synonyms (comma-separated)" value={synonyms} onChange={(e) => setSynonyms(e.target.value)} />
      <button type="submit">Submit</button>
    </form>
  );
};

export default WordForm;
```

4. App.js:

```jsx
import React from 'react';
import './App.css';
import WordForm from './WordForm';

function App() {
  return (
    <div className="App">
      <h1>Synonym Manager</h1>
      <WordForm />
    </div>
  );
}

export default App;
```

### Backend (Node.js with Express):

1. Create a new directory for the backend and initialize npm:
```bash
mkdir backend
cd backend
npm init -y
```

2. Install necessary dependencies:
```bash
npm install express mongoose
```

3. Create a file for the server (`server.js`):

```javascript
const express = require('express');
const mongoose = require('mongoose');
const bodyParser = require('body-parser');

const app = express();

app.use(bodyParser.json());

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/synonym_manager', { useNewUrlParser: true, useUnifiedTopology: true });
const db = mongoose.connection;

db.on('error', (err) => console.error('MongoDB connection error:', err));
db.once('open', () => console.log('Connected to MongoDB'));

// Define schema and model
const wordSchema = new mongoose.Schema({
  word: String,
  meaning: String,
  synonyms: [String]
});

const Word = mongoose.model('Word', wordSchema);

// Create a new word
app.post('/words', async (req, res) => {
  try {
    const { word, meaning, synonyms } = req.body;
    const newWord = new Word({ word, meaning, synonyms });
    await newWord.save();
    res.json(newWord);
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server error' });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
