        } catch (AuthenticationException e) {
            return ResponseEntity.status(401).body("Invalid username or password.");
        }
        String token = jwtUtil.generateToken(user.getUsername());
        return ResponseEntity.ok(token);
    }

    @GetMapping("/logout")
