package com.tutorialspoint;

import java.io.IOException;
import java.util.Date;
import javax.servlet.Filter;
import javax.servlet.FilterChain;
import javax.servlet.FilterConfig;
import javax.servlet.ServletException;
import javax.servlet.ServletRequest;
import javax.servlet.ServletResponse;
import javax.servlet.http.HttpServletRequest;

public class LogFilter implements Filter {

    @Override
    public void init(FilterConfig config) throws ServletException {
        // Get init parameter
        String testParam = config.getInitParameter("test-param");
        // Print the init parameter
        System.out.println("Test Param: " + testParam);
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        // Get the IP address of client machine.
        String ipAddress = request.getRemoteAddr();
        // Log the IP address and current timestamp.
        System.out.println("LogFilter : IP : " + ipAddress + " , request URI : " + ((HttpServletRequest) request).getRequestURI()
                + " , Time : " + new Date().toString());
        // Pass request back down the filter chain
        chain.doFilter(request, response);
        System.out.println("LogFilter work completed : " + ipAddress + " , request URI : "
                + ((HttpServletRequest) request).getRequestURI() + " , Time : " + new Date().toString());
    }

    @Override
    public void destroy() {
        // Called before the Filter instance is removed from service by the web container
    }
}
```

2. **Register the Filter in Spring Boot Application:**

In your main Spring Boot application class, register the `LogFilter` as a bean:

```java
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class SpringBootApp {

    public static void main(String[] args) {
        SpringApplication.run(SpringBootApp.class, args);
    }

    @Bean
    public FilterRegistrationBean<LogFilter> loggingFilter() {
        FilterRegistrationBean<LogFilter> registrationBean = new FilterRegistrationBean<>();

        registrationBean.setFilter(new LogFilter());
        registrationBean.addUrlPatterns("/*"); // Filter will apply to all URL patterns

        // Optionally set init parameters
        registrationBean.addInitParameter("test-param", "Test Value");

        return registrationBean;
    }
}
```

