// Middleware to parse JSON bodies
app.use(express.json());

// Route to save resume data to MongoDB
app.post('/resume', async (req, res) => {
  try {
    const { title, tenure, company, responsibilities } = req.body;
    const newResume = new Resume({ title, tenure, company, responsibilities });
    await newResume.save();
    res.status(201).json({ message: 'Resume data saved successfully', data: newResume });
  } catch (err) {
    console.error('Error saving resume data:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Start the server
