  about: String,
  education: [{ 
    institution: String,
    degree: String,
    year: String
  }],
  professionalExperience: [{
    title: String,
    tenure: String,
    company: String,
    responsibilities: [String]
  }],
  projects: [{
    name: String,
    description: String,
    technologies: [String]
  }]
});

// Create a model from the schema
const Resume = mongoose.model('Resume', resumeSchema);

// Middleware to parse JSON bodies
app.use(express.json());

// Route to save resume data to MongoDB
app.post('/resume', async (req, res) => {
  try {
    const {
      name,
      email,
      contactNumbers,
      about,
      education,
      professionalExperience,
      projects
    } = req.body;

    const newResume = new Resume({
      name,
      email,
      contactNumbers,
      about,
