### 🔹 `preload.js`

```js
const { contextBridge } = require('electron');
const fs = require('fs');
const path = require('path');
const marked = require('marked');

contextBridge.exposeInMainWorld('mdReader', {
  loadMarkdownFiles: () => {
    const basePath = path.join(__dirname, '..', 'public');
    const filenames = ['file1.md', 'file2.md', 'file3.md'];
    const files = filenames.map(name => {
      const content = fs.readFileSync(path.join(basePath, name), 'utf8');
      return { name, html: marked.parse(content) };
    });
    return files;
  }
});
```

---

### 🔹 `index.html`

```html
<!DOCTYPE html>
<html>
<head>
  <title>Markdown Tabs</title>
