    }
  </style>
</head>
<body>

  <div class="tabs" id="tab-buttons"></div>
  <div class="tab-content" id="tab-content"></div>

  <script>
    const files = window.mdReader.loadMarkdownFiles();

    const buttonsContainer = document.getElementById('tab-buttons');
    const contentContainer = document.getElementById('tab-content');

    files.forEach((file, idx) => {
      const btn = document.createElement('button');
      btn.textContent = file.name;
      btn.className = 'tab-button';
      if (idx === 0) btn.classList.add('active');
      btn.addEventListener('click', () => {
        document.querySelectorAll('.tab-button').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        contentContainer.innerHTML = file.html;
      });
      buttonsContainer.appendChild(btn);
    });

    // Show first by default
    contentContainer.innerHTML = files[0].html;
  </script>
</body>
</html>
```

