          prompt: `Explain the given code:\n\n${code}`,
          max_tokens: 100,
          temperature: 0.5
        })
      });
      const data = await response.json();
      setExplanation(data.choices[0].text.trim());
    } catch (error) {
      console.error('Error fetching explanation:', error);
    }
  };

  const handleChange = (event) => {
    setCode(event.target.value);
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    fetchExplanation();
  };

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <textarea
          value={code}
          onChange={handleChange}
          placeholder="Enter code to explain"
          rows={10}
          cols={50}
        />
        <button type="submit">Explain Code</button>
      </form>
      {explanation && (
        <div>
          <h2>Explanation:</h2>
          <p>{explanation}</p>
        </div>
      )}
    </div>
  );
};

export default ChatGPTExplanation;
```

