I see an issue in your code that's causing the date range filter not to work correctly. The problem is that you are converting the `occurenceDate` and the filter dates to dates with time included. To fix this, you can create a helper function that removes the time part from the dates. Here's an updated version of your component:

```jsx
import React, { useEffect, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { fetchTopics } from "../../redux/topicSlice";
import CreateTopic from "./CreateTopic";
import TopicCard from "./TopicCard";
import { fetchTags } from "../../redux/tagsSlice";
import { formatDateToDDMMMYYYY } from "../../common/commonService";

function ListTopicsByCreatedDate() {
  const topics = useSelector((state) => state.topics.data);
  const loading = useSelector((state) => state.topics.loading);
  const error = useSelector((state) => state.topics.error);
  const dispatch = useDispatch();
  const [showForm, setShowForm] = useState(false);
  const availableTags = useSelector((state) => state.tags.data);

  const [editTopic, setEditTopic] = useState(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    dispatch(fetchTopics());
    dispatch(fetchTags());
  }, [dispatch]);

  const handleEditTopic = (topic) => {
    handleCancelEdit();
    setShowForm(true);
    setEditTopic(topic);
  };

  const handleCancelEdit = () => {
    setShowForm(false);
    setEditTopic(null);
  };

  const handleCreateOrUpdateTopic = () => {
    setShowForm(false);
  };

  const removeTimeFromDate = (date) => {
    const newDate = new Date(date);
    newDate.setHours(0, 0, 0, 0);
    return newDate;
  };

  const groupTopicsByOccurenceDate = (topics) => {
    const groupedTopics = {};
    topics.forEach((topic) => {
      if (groupedTopics[topic.occurenceDate]) {
        groupedTopics[topic.occurenceDate].push(topic);
      } else {
        groupedTopics[topic.occurenceDate] = [topic];
      }
    });

    const sortedGroupedTopics = Object.entries(groupedTopics);
    sortedGroupedTopics.sort(
      (a, b) =>
        removeTimeFromDate(a[0]).getTime() - removeTimeFromDate(b[0]).getTime()
    );

    const sortedGroupedTopicsObject = {};
    sortedGroupedTopics.forEach(([key, value]) => {
      sortedGroupedTopicsObject[key] = value;
    });

    return sortedGroupedTopicsObject;
  };

  const filteredTopics = topics.filter((topic) => {
    if (!startDate || !endDate) {
      return true; // No filter applied
    }

    const topicDate = removeTimeFromDate(topic.occurenceDate);
    const startFilterDate = removeTimeFromDate(startDate);
    const endFilterDate = removeTimeFromDate(endDate);

    return topicDate >= startFilterDate && topicDate <= endFilterDate;
  });

  const groupedTopics = groupTopicsByOccurenceDate(filteredTopics);

  const listStyle = {
    display: "flex",
    flexDirection: "column",
  };

  const groupStyle = {
    border: "1px solid #ccc",
    margin: "10px",
    padding: "10px",
  };

  const itemStyle = {
    border: "1px solid #ccc",
    padding: "10px",
  };

