      {loading === "pending" && <p>Loading topics...</p>}
      {error && <p>Error: {error}</p>}

      {!showForm && <button onClick={() => setShowForm(true)}>Add</button>}

      {showForm && (
        <CreateTopic
          topic={editTopic}
          onSave={handleCreateOrUpdateTopic}
          onCancelEdit={handleCancelEdit}
        />
      )}

      {loading === "fulfilled" && (
        <div style={listStyle}>
          <div>
            <label htmlFor="startDate">Start Date: </label>
            <input
              type="date"
              id="startDate"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
            <label htmlFor="endDate">End Date: </label>
            <input
              type="date"
              id="endDate"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </div>
          {Object.keys(groupedTopics).map((occurenceDate) => (
            <div key={occurenceDate} style={groupStyle}>
              <h3>{formatDateToDDMMMYYYY(occurenceDate)}</h3>
              {groupedTopics[occurenceDate].map((topic) => (
                <div
                  key={topic.topicId}
                  style={itemStyle}
                  onDoubleClick={() => handleEditTopic(topic)}
                >
                  <TopicCard topic={topic} tags={availableTags} />
                </div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default ListTopicsByCreatedDate;
```

I've added a `removeTimeFromDate` function to remove the time part from dates. This will make the date range filter work as expected.

