```jsx
import React, { useState } from 'react';
import { BACKEND_APPLICATION_BASE_URL } from '../common/globalConstants'; // Import your backend base URL

function TagsCreate() {
  const [tagData, setTagData] = useState({
    name: '',
    description: '',
  });

  const [isCreating, setIsCreating] = useState(false);
  const [createError, setCreateError] = useState(null);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setTagData({ ...tagData, [name]: value });
  };

  const handleCreateTag = async (e) => {
    e.preventDefault();
    setIsCreating(true);
    setCreateError(null);

    try {
      const response = await fetch(`${BACKEND_APPLICATION_BASE_URL}/tags`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(tagData),
      });

      if (!response.ok) {
        throw new Error(`Failed to create the tag: ${response.status} - ${response.statusText}`);
      }

      // Clear the form and reset the state
      setTagData({
        name: '',
        description: '',
      });

      setIsCreating(false);
    } catch (error) {
      setCreateError(error.message);
      setIsCreating(false);
    }
  };

  return (
    <div>
      <h2>Create Tag</h2>
      <form onSubmit={handleCreateTag}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={tagData.name}
            onChange={handleInputChange}
            required
          />
        </div>
        <div>
          <label htmlFor="description">Description:</label>
          <textarea
            id="description"
            name="description"
            value={tagData.description}
            onChange={handleInputChange}
          />
        </div>
        <div>
          <button type="submit" disabled={isCreating}>
            {isCreating ? 'Creating...' : 'Create Tag'}
          </button>
        </div>
        {createError && <p>Error: {createError}</p>}
      </form>
    </div>
  );
}

export default TagsCreate;
```

In this component:

- We import the `BACKEND_APPLICATION_BASE_URL` from your constants to use as the API endpoint.

- We use the `useState` hook to manage the form input, loading state (`isCreating`), and error state (`createError`).

