import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { createTag, updateTag } from './tagsSlice'; // Import your Redux Toolkit actions

function TagsCreate({ tag }) {
  const dispatch = useDispatch();

  const [tagData, setTagData] = useState({
    name: '',
    description: '',
  });

  const [isCreating, setIsCreating] = useState(false);
  const [createError, setCreateError] = useState(null);

  useEffect(() => {
    if (tag) {
      // If the "tag" prop is provided, prefill the form fields for editing
      setTagData({
        name: tag.name,
        description: tag.description,
      });
    }
  }, [tag]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setTagData({ ...tagData, [name]: value });
  };

  const handleSaveTag = async (e) => {
    e.preventDefault();
    setIsCreating(true);
    setCreateError(null);

    try {
      if (tag) {
        // If a tag prop is provided, it's an edit operation
        await dispatch(updateTag({ ...tag, ...tagData }));
      } else {
        // If no tag prop is provided, it's a create operation
        await dispatch(createTag(tagData));
      }

      // Clear the form and reset the state
      setTagData({
        name: '',
        description: '',
      });

      setIsCreating(false);
    } catch (error) {
      setCreateError(error.message);
      setIsCreating(false);
    }
  };

  return (
    <div>
      <h2>{tag ? 'Edit Tag' : 'Create Tag'}</h2>
      <form onSubmit={handleSaveTag}>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={tagData.name}
            onChange={handleInputChange}
            required
          />
        </div>
        <div>
          <label htmlFor="description">Description:</label>
          <textarea
            id="description"
            name="description"
            value={tagData.description}
            onChange={handleInputChange}
          />
        </div>
        <div>
          <button type="submit" disabled={isCreating}>
            {isCreating ? 'Saving...' : tag ? 'Save Changes' : 'Create Tag'}
          </button>
        </div>
        {createError && <p>Error: {createError}</p>}
      </form>
    </div>
  );
}

export default TagsCreate;
```

