async function insertAudit(auditData) {
  try {
    const audit = new Audit(auditData);

    if (auditData.action === 'EDIT') {
      // Handle 'EDIT' action - Compare and store the differences
      const originalAudit = await Audit.findOne({ _id: auditData.auditId });

      if (originalAudit) {
        const changes = {};

