        if (auditData.subaction !== originalAudit.subaction) {
          changes.subaction = {
            oldValue: originalAudit.subaction,
            newValue: auditData.subaction,
          };
        }

        // Store the changes object in the audit record
        audit.changes = changes;
      }
    }

    await audit.save();
    return audit;
  } catch (error) {
    throw new Error('Failed to insert audit record: ' + error.message);
  }
}

module.exports = {
  insertAudit,
};
```

