  const handleDoubleClick = (tag) => {
    // Set the tag to edit when double-clicked
    setTagToEdit(tag);
  };

  const clearEditState = () => {
    // Clear the edit state when not editing
    setTagToEdit(null);
  };

  const handleUpdateTag = (updatedTag) => {
