      {loading ? (
        <p>Loading tags...</p>
      ) : error ? (
        <p>Error: {error}</p>
      ) : (
        <ul>
          {tags.map((tag) => (
            <li key={tag._id}>
              <strong>{tag.name}</strong>
              <p>{tag.description}</p>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

