2. **App.js**:
```jsx
import React, { useState, useEffect } from 'react';
import CreateTweet from './CreateTweet';
import ListTweets from './ListTweets';
import UpdateTweet from './UpdateTweet';

function App() {
  const [tweets, setTweets] = useState([]);
  const [selectedTweet, setSelectedTweet] = useState(null);

  useEffect(() => {
    fetch('/tweets')
      .then(response => response.json())
      .then(data => setTweets(data))
      .catch(error => console.error('Error fetching tweets:', error));
  }, []);

  const handleTweetCreated = (newTweet) => {
    setTweets([...tweets, newTweet]);
  };

  const handleTweetUpdated = (updatedTweet) => {
    const updatedTweets = tweets.map(tweet =>
      tweet._id === updatedTweet._id ? updatedTweet : tweet
    );
    setTweets(updatedTweets);
    setSelectedTweet(null);
  };

  return (
    <div>
      <h1>Tweet App</h1>
      <CreateTweet onTweetCreated={handleTweetCreated} />
      {selectedTweet && (
        <UpdateTweet tweet={selectedTweet} onUpdate={handleTweetUpdated} />
      )}
      <ListTweets tweets={tweets} onUpdate={setSelectedTweet} />
    </div>
  );
}

