First, make sure you have Node.js installed on your system. Then, install the `kafka-node` package, which is a popular library for interacting with Kafka from Node.js:

```bash
npm install kafka-node
```

Now, let's create the producer and consumer scripts:

**Producer:**

```javascript
const kafka = require('kafka-node');
const Producer = kafka.Producer;
const client = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const producer = new Producer(client);
const topic = 'test-topic';

producer.on('ready', () => {
    console.log('Producer is ready');

    const message = {
        topic: topic,
        messages: 'Hello Kafka!',
        partition: 0
    };

    producer.send([message], (err, data) => {
        if (err) {
            console.error('Error sending message:', err);
        } else {
            console.log('Message sent:', data);
        }
        process.exit(0);
    });
});

producer.on('error', (err) => {
    console.error('Producer error:', err);
});
```

**Consumer:**

```javascript
const kafka = require('kafka-node');
const Consumer = kafka.Consumer;
const client = new kafka.KafkaClient({ kafkaHost: 'localhost:9092' });
const consumer = new Consumer(
    client,
    [{ topic: 'test-topic', partition: 0 }],
    { autoCommit: false }
);

consumer.on('message', (message) => {
    console.log('Received message:', message.value);
});

consumer.on('error', (err) => {
    console.error('Consumer error:', err);
});

process.on('SIGINT', () => {
    consumer.close(true, () => {
        console.log('Consumer closed');
        process.exit(0);
    });
});
```

Save these scripts in separate files, for example, `producer.js` and `consumer.js`. Make sure your Kafka broker is running on `localhost:9092`.

