import com.amazonaws.HttpMethod;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3ClientBuilder;
import com.amazonaws.services.s3.model.GeneratePresignedUrlRequest;
import java.net.URL;
import java.util.Date;

public class S3PresignedUrlExample {
    public static void main(String[] args) {
        AmazonS3 s3Client = AmazonS3ClientBuilder.standard()
                .withRegion("your-aws-region")
                .withCredentials(new AWSStaticCredentialsProvider(
                        new BasicAWSCredentials("your-access-key", "your-secret-key")))
                .build();

        String bucketName = "your-bucket-name";
        String objectKey = "path/to/your/image.jpg";
        Date expiration = new Date(System.currentTimeMillis() + 3600000); // 1 hour from now

        GeneratePresignedUrlRequest generatePresignedUrlRequest =
                new GeneratePresignedUrlRequest(bucketName, objectKey)
                        .withMethod(HttpMethod.GET)
                        .withExpiration(expiration);

        URL preSignedUrl = s3Client.generatePresignedUrl(generatePresignedUrlRequest);

        System.out.println("Pre-signed URL for downloading the image:");
        System.out.println(preSignedUrl);
    }
}
```

