                LocalDate localDate = triggerDate.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
                if (recurrence == Recurrence.QUARTERLY) {
                    int quarter = localDate.get(IsoFields.QUARTER_OF_YEAR);
                    return "Q" + quarter + " " + localDate.getYear();
                } else if (recurrence == Recurrence.ANNUALLY) {
                    return "Year_" + localDate.getYear();
                } else if (recurrence == Recurrence.BIANNUALLY) {
                    int month = localDate.getMonthValue();
                    return (month <= 5 ? "First half " : "Second Half ") + localDate.getYear();
                }
            }
            case BIMONTHLY -> {
                LocalDate currentDate = triggerDate.toInstant().atZone(ZoneId.systemDefault()).toLocalDate();
                LocalDate firstDayOfMonth = currentDate.withDayOfMonth(1);
                int lastDayOfMonth = currentDate.lengthOfMonth();
                LocalDate middleOfMonth = firstDayOfMonth.plusDays(lastDayOfMonth / 2);

                LocalDate endDate;
                if (currentDate.isBefore(middleOfMonth) || currentDate.isEqual(middleOfMonth)) {
                    endDate = middleOfMonth;
                } else {
                    firstDayOfMonth = middleOfMonth.plusDays(1);
                    endDate = firstDayOfMonth.withDayOfMonth(lastDayOfMonth);
                }

                return firstDayOfMonth.format(DateTimeFormatter.ofPattern("d")) +
                        "-" +
                        endDate.format(DateTimeFormatter.ofPattern("d MMM yyyy"));
            }
        }
        return "";
    }

    public enum Recurrence {
        MONTHLY,
        DAILY,
        QUARTERLY,
        ANNUALLY,
        BIANNUALLY,
        BIMONTHLY
    }
}
