import React from "react";
import "./Card.css";
import { camelCaseToTitleCase } from "../../../utils/helper-utils";

const FieldValueType = {
    SingleValue: "single-value",
    ArrayValue: "array-value",
};

// Default renderer for individual items
const defaultItemRenderer = (item) => {
    if (!item) return <span>N/A</span>;
    if (typeof item === "object" && !Array.isArray(item)) {
        return (
            <div title="Rendering nested object">
                {renderCard({ objectToBeRendered: item })}
            </div>
        );
    }
    return item;
};

// Merged Field component to handle both single and array values
const Field = ({
    type = FieldValueType.SingleValue,
    label,
    value,
    renderItem = defaultItemRenderer,
}) => (
    <div className="card-field">
        <strong>{label}:</strong>{" "}
        {type === FieldValueType.ArrayValue ? (
            value?.length > 0 ? (
                <ul>
                    {value.map((item, index) => (
                        <li key={index}>{renderItem(item)}</li>
                    ))}
                </ul>
            ) : (
                <span>N/A</span>
            )
        ) : (
            renderItem(value)
        )}
    </div>
);

const Card = ({ title, fields = [] }) => (
    <div className="card">
        {title && (
            <div className="card-header">
                <span>{title}</span>
            </div>
        )}
        <div className="card-body">
            {fields.length > 0 ? (
                fields.map(({ type, label, value, renderItem }, idx) => (
                    <Field
                        key={idx}
                        type={type}
                        label={label}
                        value={value}
                        renderItem={renderItem}
                    />
                ))
            ) : (
                <span>No fields provided</span>
            )}
        </div>
    </div>
);

const renderCard = ({ title, objectToBeRendered }) => {
    if (!objectToBeRendered || typeof objectToBeRendered !== "object") {
        return <>Invalid object provided for rendering into a card</>;
    }

    if (Array.isArray(objectToBeRendered)) {
        return (
            <div>
                {objectToBeRendered.length > 0 ? (
                    objectToBeRendered.map((item, index) => (
                        <div key={index}>
                            {typeof item === "object" ? (
                                renderCard({
                                    title: `${title || "Item"} ${index + 1}`,
                                    objectToBeRendered: item,
                                })
                            ) : (
                                <Field
                                    label={`${title || "Item"} ${index + 1}`}
                                    value={item}
                                />
                            )}
                        </div>
                    ))
                ) : (
                    <span>No items to display in the array</span>
                )}
            </div>
        );
    }

    // Render object fields
    const fields = Object.keys(objectToBeRendered).map((key) => ({
        type: Array.isArray(objectToBeRendered[key])
            ? FieldValueType.ArrayValue
            : FieldValueType.SingleValue,
        label: camelCaseToTitleCase(key),
        value: objectToBeRendered[key],
    }));

    return <Card title={title} fields={fields} />;
};

export default Card;
export { FieldValueType, renderCard };
