  onClose: () => void;
};

const ModalV3 = ({ children, onClose }: ModalProps) => {
  const {
    GLOBAL_APPLICATION_STYLES: {
      backdrop,
      modal,
      modalCloseButton: closeButton,
    }, // Assuming `closeButton` is added for styling the cancel button
  } = useGlobalStyles();

