export const withModal = <P extends object>(
  WrappedComponent: React.ComponentType<P>
) => {
  // The component that will be returned by the HOC
  return (props: P & { onClose: () => void }) => {
    const { onClose } = props;

    return (
      <ModalV3 onClose={onClose}>
        <WrappedComponent {...props} />
      </ModalV3>
    );
  };
