    if (!input) return input;
    return input
        .split('-')                // Split by hyphen
        .map((word, index) =>
            // index === 0 ? word : word.charAt(0).toUpperCase() + word.slice(1)
            word.charAt(0).toUpperCase() + word.slice(1)
        ) // Capitalize each word
        .join('');                 // Join words back together
}

