    }
    return item;
};

// Merged Field component to handle both single and array values
const Field = ({ label, title, value, renderItem = defaultItemRenderer }) => (
    <div className="card-field">
        <strong title={title}>{label}:</strong> {renderItem(value, title)}
    </div>
);

const Card = ({ title, fields = [] }) => (
    <div className="card">
        {title && (
            <div className="card-header">
                <span>{title}</span>
            </div>
        )}
        <div className="card-body">
            {fields.length > 0 ? (
                fields.map(({ label, value, renderItem, title }, idx) => (
                    <Field
                        key={idx}
                        label={label}
                        title={title}
                        value={value}
                        renderItem={renderItem}
                    />
                ))
            ) : (
                <span>No fields provided</span>
            )}
        </div>
    </div>
);

const renderCard = ({ title, objectToBeRendered, objectName = "providedObject" }) => {
    if (!objectToBeRendered || typeof objectToBeRendered !== "object") {
        return <span>Invalid object provided for rendering into a card</span>;
    }

    if (Array.isArray(objectToBeRendered)) {
        // Handle arrays by delegating to renderListSection
        return renderListSection(
            title,
            objectToBeRendered,
            (item, idx) =>
                typeof item === "object" ? (
                    renderCard({ objectToBeRendered: item, objectName: `${objectName}[${idx}]` })
                ) : (
                    <div key={idx}>- {item}</div>
                ),
            "No items to display in the array"
        );
    }

    // Render object fields with proper titles
    const fields = Object.keys(objectToBeRendered).map((key) => ({
        label: camelCaseToTitleCase(key),
        value: objectToBeRendered[key],
        title: `${objectName}.${key}`, // Detailed title for nested objects
    }));

    return <Card title={title} fields={fields} />;
};

export default Card;
export { FieldValueType, renderCard };
