```jsx
import React, { useEffect, useRef, useCallback } from "react";
import { FaTimes } from "react-icons/fa";
import './ModalV3_1.css';

const ModalV3 = ({ children, onClose }) => {
  const modalRef = useRef();

  // Focus trap to keep focus inside the modal
  const focusTrap = useCallback((e) => {
    if (!modalRef.current.contains(e.target)) {
      e.stopPropagation();
      modalRef.current.focus();
    }
  }, []);

  // Handle 'Escape' key press to close the modal
  const handleEscKeyPress = useCallback(
    (event) => {
      if (event.key === "Escape") {
        onClose();
      }
    },
    [onClose]
  );

  useEffect(() => {
    document.addEventListener("keydown", handleEscKeyPress);
    document.addEventListener("focusin", focusTrap);
    return () => {
      document.removeEventListener("keydown", handleEscKeyPress);
      document.removeEventListener("focusin", focusTrap);
    };
  }, [handleEscKeyPress, focusTrap]);

  useEffect(() => {
    // Add visible class to trigger animation
    setTimeout(() => {
      modalRef.current?.classList.add("visible");
    }, 10);
  }, []);

  return (
    <>
      <div className="modal-backdrop visible" onClick={onClose}></div>
      <dialog
        open
        className="modal"
        ref={modalRef}
        aria-modal="true"
        aria-labelledby="modal-title"
      >
        <button
          className="modal-close-button"
          onClick={onClose}
          aria-label="Close modal"
        >
          <FaTimes />
        </button>
        <div className="modal-content">{children}</div>
      </dialog>
    </>
  );
};

// Higher-Order Component (HOC) for wrapping components with a modal
export const withModal = (WrappedComponent) => (props) => {
  const { onClose, ...restProps } = props;

  return (
    <ModalV3 onClose={onClose}>
      <WrappedComponent {...restProps} />
    </ModalV3>
  );
};

const ExampleComponent = () => {
  return <div>Hello, this is a modal content!</div>;
};

// Wrap MyComponent with the modal
export const ExampleComponentWithModal = withModal(ExampleComponent);

