import { useMutation } from '@apollo/client';
import { UPSERT_RESUME } from '../common/gql/mutations'; // Import the mutation from the mutations file

const ResumeForm = ({ addResume, resume, onCancel }) => {
    // State for form inputs
    const [formData, setFormData] = useState({
        introduction: '',
        summary: '',
        companies: [], // Array to store company names
    });

    // Set initial form data if a resume is provided
    useEffect(() => {
        if (resume) {
            setFormData({
                uniqueId: resume.uniqueId || '',
                introduction: resume.introduction || '',
                summary: resume.summary || '',
                companies: resume.companies || [], // Initialize companies with resume data
            });
        }
    }, [resume]);

    // Mutation hook for upserting a resume
    const [upsertResume] = useMutation(UPSERT_RESUME);

    // Function to handle form submission
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            // Execute the mutation with form data
            const { data } = await upsertResume({
                variables: {
                    resume: formData,
                },
            });

            // Add the new or updated resume to the list
            addResume(data.upsertResume);

            // Reset form inputs
            setFormData({
                introduction: '',
                summary: '',
                companies: [], // Reset companies array
            });
        } catch (error) {
            console.error('Error creating or updating resume:', error);
        }
    };

    // Function to handle input changes
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    // Function to handle adding a company
    const handleAddCompany = () => {
        const { companies: existingCompanies, ...rest } = formData;
        const companyName = prompt('Enter company name:'); // Prompt for company name
        if (companyName) {
            setFormData({
                ...rest,
                companies: [...existingCompanies, companyName],
            });
        }
    };

    // Function to handle removing a company
    const handleRemoveCompany = (index) => {
        const { companies: existingCompanies, ...rest } = formData;
        const updatedCompanies = [...existingCompanies];
        updatedCompanies.splice(index, 1); // Remove company at index
        setFormData({
            ...rest,
            companies: updatedCompanies,
        });
    };

    return (
        <>
            <h3>{resume ? 'Edit Resume' : 'Add Resume'}</h3>
            <form onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="introduction">Introduction:</label>
                    <input
                        type="text"
