To segregate the server code into meaningful files, we can organize it into modules based on functionality. Here's how you can do it:

1. **Create a `models` directory:** This directory will contain the Mongoose models for MongoDB.

2. **Create a `schemas` directory:** This directory will contain the GraphQL schema definitions.

3. **Create a `resolvers` directory:** This directory will contain the resolvers for GraphQL queries and mutations.

4. **Create a `services` directory:** This directory will contain the Apollo Server setup and connection to MongoDB.

Here's the directory structure:

```
src/
│
├── models/
│   └── resume.js
│
├── schemas/
│   └── resumeSchema.js
│
├── resolvers/
│   └── resumeResolvers.js
│
└── services/
    └── apolloServer.js
```

Now, let's split the code accordingly:

**1. `models/resume.js`:**

```javascript
const mongoose = require('mongoose');
const { Schema } = mongoose;

const companySchema = new Schema({
  uniqueId: { type: String, unique: true, default: () => uuidv4() },
  name: String,
  details: String,
  projects: [{
    uniqueId: { type: String, unique: true, default: uuidv4 },
    name: String,
    details: String
  }]
});

const educationSchema = new Schema({
  uniqueId: { type: String, unique: true, default: () => uuidv4() },
  name: String,
  details: String
});

const resumeSchema = new Schema({
  uniqueId: { type: String, default: () => uuidv4() },
  introduction: String,
  summary: String,
  companies: [companySchema],
  educations: [educationSchema]
});

module.exports = mongoose.model('Resume', resumeSchema);
```

**2. `schemas/resumeSchema.js`:**

```javascript
const { gql } = require('apollo-server-express');

const typeDefs = gql`
  type Company {
    uniqueId: String!
    name: String!
    details: String!
    projects: [Project]
  }

  type Project {
    uniqueId: String!
    name: String!
    details: String!
  }

  type Education {
    uniqueId: String!
    name: String!
    details: String!
  }

  type Resume {
    uniqueId: String!
    introduction: String!
    summary: String!
    companies: [Company]
    educations: [Education]
  }

  input CompanyInput {
    name: String!
    details: String!
    projects: [ProjectInput]
  }

  input ProjectInput {
    name: String!
    details: String!
  }

  input EducationInput {
    name: String!
    details: String!
  }

  input ResumeInput {
    introduction: String!
    summary: String!
    companies: [CompanyInput]
    educations: [EducationInput]
  }

  type Query {
    getResume(uniqueId: String!): Resume
    getAllResumes: [Resume]
  }

  type Mutation {
    upsertResume(resume: ResumeInput!): Resume
  }
`;

module.exports = typeDefs;
```

**3. `resolvers/resumeResolvers.js`:**

```javascript
const Resume = require('../models/resume');

const resolvers = {
  Query: {
    getResume: async (_, { uniqueId }) => {
      return await Resume.findOne({ uniqueId });
    },
    getAllResumes: async () => {
      return await Resume.find();
    }
  },
  Mutation: {
    upsertResume: async (_, { resume }) => {
      return await Resume.findOneAndUpdate(
        { uniqueId: resume.uniqueId },
        resume,
        { upsert: true, new: true }
      );
    },
  },
};

module.exports = resolvers;
```

**4. `services/apolloServer.js`:**

```javascript
const express = require('express');
const { ApolloServer } = require('apollo-server-express');
const mongoose = require('mongoose');
const typeDefs = require('../schemas/resumeSchema');
const resolvers = require('../resolvers/resumeResolvers');

async function startApolloServer() {
  const server = new ApolloServer({ typeDefs, resolvers });
  await server.start();

  const app = express();
  server.applyMiddleware({ app });

  await mongoose.connect('mongodb://127.0.0.1:27017/ms_playground_ex03_resume_db', {
    useNewUrlParser: true,
    useUnifiedTopology: true,
  });

  const PORT = process.env.PORT || 4000;
  app.listen(PORT, () => {
    console.log(`Server ready at http://localhost:${PORT}${server.graphqlPath}`);
  });
}

startApolloServer().catch(error => console.error(error));
```

Now, you can run your application by executing `node src/services/apolloServer.js`.

