To refactor the code, I’ll follow these key steps to streamline it:

1. Define `generateMetrics` as a utility function within `ReportComponent`.
2. Standardize `metricsArr` generation for each report type using `generateMetrics`.
3. Use a shared component for common behavior like rendering checkboxes for metrics selection.

Here’s the complete refactored code:

```javascript
import React, { useMemo, useState } from "react";
import HoverActions from "../../../common/components/HoverActions";
import JSONDataViewer from "../../../common/components/JSONDataViewer";

// Report Types
const AnalyticsReportType = {
    ALL_RESUMES: "all-resumes",
    SELECTED_RESUME: "selected-resume",
    SELECTED_COMPANY: "selected-company",
    SELECTED_PROJECT: "selected-project",
};

// Utility to generate metrics array
const generateMetrics = (type, data) => {
    let incr = 0;
    switch (type) {
        case AnalyticsReportType.SELECTED_RESUME:
            return [
                { id: `rr_${++incr}`, name: "Total Companies", value: data.companies?.length || 0 },
                {
                    id: `rr_${++incr}`,
                    name: "Total Projects",
                    value: data.companies?.reduce((acc, comp) => acc + (comp.projects?.length || 0), 0) || 0,
                },
            ];
        case AnalyticsReportType.SELECTED_COMPANY:
            return [
                { id: `cr_${++incr}`, name: "Total Projects", value: data.projects?.length || 0 },
                {
                    id: `cr_${++incr}`,
                    name: "Project Names",
                    value: data.projects?.map((proj) => proj.name).join(", ") || "No projects",
                },
            ];
        case AnalyticsReportType.SELECTED_PROJECT:
            return [
                { id: `pr_${++incr}`, name: "Project Name", value: data.name || "Unnamed" },
                {
                    id: `pr_${++incr}`,
                    name: "Tech Stack",
                    value: data.processedDetails?.metadata?.techStack?.join(", ") || "No tech stack",
                },
            ];
        default:
            return [
                {
                    id: `ar_${++incr}`,
                    name: "Total Resumes",
                    value: data.length || 0,
                },
                {
                    id: `ar_${++incr}`,
                    name: "Resume-Wise Company Count",
                    value: data.map((resume) => `${resume.name || "Unnamed"}: ${resume.companies?.length || 0}`).join("; "),
                },
            ];
    }
};

// Metric Component
const Metric = ({ name, value }) => (
    <div>
        <b>{name.toUpperCase()}: </b>
        {value}
    </div>
);

// Checkbox list for metric selection
const MetricSelection = ({ metrics, selectedMetrics, onToggleMetric, onToggleAll }) => (
    <HoverActions
        actions={[
            <label key="all-metrics">
                <input
                    type="checkbox"
                    checked={selectedMetrics.length === metrics.length}
                    onChange={(e) => onToggleAll(e.target.checked)}
                />
                All Metrics
            </label>,
            ...metrics.map((metric) => (
                <label key={metric.id}>
                    <input
                        type="checkbox"
                        checked={selectedMetrics.includes(metric.id)}
                        onChange={() => onToggleMetric(metric.id)}
                    />
                    {metric.name}
                </label>
            )),
        ]}
    />
);

// Report Component for rendering different reports based on type
const ReportComponent = ({ analyticsReportType, data }) => {
    const [selectedMetrics, setSelectedMetrics] = useState([]);
    const metricsArr = useMemo(() => generateMetrics(analyticsReportType, data), [analyticsReportType, data]);

    const handleToggleMetric = (id) =>
        setSelectedMetrics((prev) =>
            prev.includes(id) ? prev.filter((metricId) => metricId !== id) : [...prev, id]
        );

    const handleToggleAllMetrics = (isChecked) =>
        setSelectedMetrics(isChecked ? metricsArr.map((metric) => metric.id) : []);

    return (
        <div>
            <h2>{analyticsReportType.replace(/-/g, " ").toUpperCase()} REPORT</h2>
            <MetricSelection
                metrics={metricsArr}
                selectedMetrics={selectedMetrics}
                onToggleMetric={handleToggleMetric}
                onToggleAll={handleToggleAllMetrics}
            />
            {metricsArr
                .filter(({ id }) => selectedMetrics.includes(id))
                .map((metric) => (
                    <Metric key={metric.id} name={metric.name} value={metric.value} />
                ))}
            <JSONDataViewer metadata={{ selectedMetrics }} title="Selected Metrics" />
        </div>
    );
};

// Main Analytics Report Component
const AnalyticsReport = ({ analyticsReportType = "", data = null }) => {
    if (!Object.values(AnalyticsReportType).includes(analyticsReportType)) {
        return <div>Invalid AnalyticsReportType selected: {`'${analyticsReportType}'`}</div>;
    } else if (data === null) {
        return <div>Null data provided</div>;
    }

    return (
        <div>
            <h2>AnalyticsReport for: <b>{analyticsReportType}</b></h2>
            <ReportComponent analyticsReportType={analyticsReportType} data={data} />
        </div>
    );
};

export default AnalyticsReport;
export { AnalyticsReportType };
```

### Explanation

1. **`generateMetrics`**: A utility function within `ReportComponent` creates an array of metrics based on `analyticsReportType`.
2. **`MetricSelection`**: This component handles the rendering of checkboxes for each metric.
3. **`ReportComponent`**: Renders the report, including metric selection and metric values.
4. **`AnalyticsReport`**: Validates `analyticsReportType` and `data` and passes them to `ReportComponent`.

This refactor enhances modularity, optimizes reusability, and improves readability. The common logic for metric generation, selection, and display is encapsulated for easier maintenance.

