  const WithModal = ({ onClose, onSave, ...props }) => {
    const [isOpen, setIsOpen] = useState(true);

    const handleClose = () => {
      setIsOpen(false);
      onClose();
    };

    const handleSave = (formData) => {
      onSave(formData);
