const { gql } = require('apollo-server-express');
const { GraphQLScalarType, Kind } = require('graphql');

// Define custom scalar type JSON
const JSONScalar = new GraphQLScalarType({
  name: 'JSON',
  description: 'Custom JSON scalar type',
  serialize(value) {
    return value; // JSON can be serialized directly
  },
  parseValue(value) {
    return value; // JSON can be parsed directly from value
  },
  parseLiteral(ast) {
    switch (ast.kind) {
      case Kind.STRING:
      case Kind.BOOLEAN:
        return ast.value;
      case Kind.INT:
      case Kind.FLOAT:
        return parseFloat(ast.value);
      case Kind.OBJECT:
        const value = Object.create(null);
        ast.fields.forEach(field => {
          value[field.name.value] = parseLiteral(field.value);
        });
        return value;
      case Kind.LIST:
        return ast.values.map(parseLiteral);
      default:
        return null;
    }
  },
});

// Define GraphQL type definitions
const typeDefs = gql`
  scalar JSON

  type Company {
    uniqueId: String!
    name: String!
    details: String!
    projects: [Project]
  }

  type Project {
    uniqueId: String!
    name: String!
    details: String!
  }

  type Education {
    uniqueId: String!
    name: String!
    details: String!
  }

  type ProcessedDetails {
    rawText: String!
    textType: String!
    metadata: JSON!
  }

  type Resume {
    uniqueId: String!
    introduction: String!
    summary: String!
    companies: [Company]
    educations: [Education]
    processedDetails: ProcessedDetails
  }

  input CompanyInput {
    uniqueId: String
    name: String!
    details: String!
    projects: [ProjectInput]
  }

  input ProjectInput {
    uniqueId: String
    name: String!
    details: String!
  }

  input EducationInput {
    uniqueId: String
    name: String!
    details: String!
  }

  input ProcessedDetailsInput {
    rawText: String!
    textType: String!
    metadata: JSON!
  }

  input ResumeInput {
    uniqueId: String
    introduction: String!
    summary: String!
    companies: [CompanyInput]
    educations: [EducationInput]
    processedDetails: ProcessedDetailsInput
  }

  type Query {
    getResume(uniqueId: String!): Resume
    getAllResumes: [Resume]
  }

  type Mutation {
    upsertResume(resume: ResumeInput!): Resume
  }
`;

module.exports = { typeDefs, JSONScalar };
