One good practice to show company data in the Resume form is to use a separate component for adding or selecting companies. This approach makes the form more modular and reusable. Here's how you can refactor the `ResumeForm` component to achieve this:

```jsx
import React, { useState, useEffect } from 'react';
import { useMutation } from '@apollo/client';
import { UPSERT_RESUME } from '../common/gql/mutations'; // Import the mutation from the mutations file
import CompanyInput from './CompanyInput'; // Import the CompanyInput component

const ResumeForm = ({ addResume, resume, onCancel }) => {
    // State for form inputs
    const [formData, setFormData] = useState({
        introduction: '',
        summary: '',
        companies: [], // Initialize companies array
    });

    // Set initial form data if a resume is provided
    useEffect(() => {
        if (resume) {
            setFormData({
                uniqueId: resume.uniqueId || '',
                introduction: resume.introduction || '',
                summary: resume.summary || '',
                companies: resume.companies || [], // Set companies array from resume
            });
        }
    }, [resume]);

    // Mutation hook for upserting a resume
    const [upsertResume] = useMutation(UPSERT_RESUME);

    // Function to handle form submission
    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            // Execute the mutation with form data
            const { data } = await upsertResume({
                variables: {
                    resume: formData,
                },
            });

            // Add the new or updated resume to the list
            addResume(data.upsertResume);

            // Reset form inputs
            setFormData({
                introduction: '',
                summary: '',
                companies: [],
            });
        } catch (error) {
            console.error('Error creating or updating resume:', error);
        }
    };

    // Function to handle input changes
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value,
        });
    };

    // Function to handle company selection or addition
    const handleCompanyChange = (selectedCompanies) => {
        setFormData({
            ...formData,
            companies: selectedCompanies,
        });
    };

    return (
        <>
            <h3>{resume ? "Edit Resume" : "Add Resume"}</h3>
            <form onSubmit={handleSubmit}>
                <div>
                    <label htmlFor="introduction">Introduction:</label>
                    <input
                        type="text"
                        id="introduction"
                        name="introduction"
                        value={formData.introduction}
                        onChange={handleInputChange}
