                });
            }
        }

        // Nested validation
        if (nestedValidation && isObject(value)) {
            nestedValidation(value, messages, fieldName);
        }
    });
};

const validateMetadata = (metadata, messages, parentField) =>
    validateFields(metadata, [
        {
            field: "summarizedIntroduction",
            type: "array",
            isRequired: true,
            customValidation: (summarizedIntroduction) => ({
                passed: isArrayOfStrings(summarizedIntroduction),
                customValidationMessage: "should contain array of strings.",
            })
        },
        {
            field: "personalDetails",
            type: "object",
            isRequired: true,
            customValidation: (personalDetails) => ({
                passed: !isArray(personalDetails),
                customValidationMessage: "should not contain an array.",
            })
        },
        {
            field: "expertises",
            type: "array",
            isRequired: true,
            customValidation: (expertises) => ({
                passed: expertises.every(isObject),
                customValidationMessage: "should contain an array of objects.",
            })
        }
    ], messages, parentField);

const validateProcessedDetails = (details, messages, parentField) =>
    validateFields(details, [
        { field: "rawText", type: "string", isRequired: true },
        { field: "textType", type: "string", isRequired: true },
        { field: "metadata", type: "object", isRequired: true, nestedValidation: validateMetadata }
    ], messages, parentField);

const validateDataForType = (data, type) => {
    const messages = [];
    if (!Object.values(ItemType).includes(type)) {
        messages.push({
            type: ValidationMessageType.ERROR,
            message: `Invalid type provided: ${type}`,
        });
    } else {
        validateFields(data, [
            { field: "uniqueId", type: "string", isRequired: true },
            { field: "name", type: "string", isRequired: true },
            { field: "processedDetails", type: "object", isRequired: true, nestedValidation: validateProcessedDetails },
        ], messages);
    }

    return {
        validData: !messages.some(msg => msg.type === ValidationMessageType.ERROR),
        messages: messages.length ? messages : [{ type: ValidationMessageType.OK, message: "All data validated successfully" }],
    };
};

export {
    ItemType,
    validateDataForType,
    ValidationMessageType,
    isUndefined,
    isObject,
    isString,
    isArray,
    isArrayOfStrings
};
```

This approach keeps `messages` unified, with `validData` calculated based on `ERROR`-type messages in `validateDataForType`, making the structure both streamlined and effective for deeply nested validations.

