import { UPSERT_RESUME } from '../common/gql/mutations'; 
import { resumeItemStyle as resumeFormStyle } from '../common/styles/ResumeComponentsStyle';
import CustomButton from '../common/components/CustomButton';
import EditorModal from './EditorModal';

const ResumeForm = ({ addResume, resume, onCancel }) => {
    const [formData, setFormData] = useState({
        introduction: '',
        summary: resume ? resume.summary : '', // Initialize summary with resume data
