```javascript
// Import required modules
const express = require('express');
const mongoose = require('mongoose');
const { Kafka } = require('kafkajs');

// Create Express app
const app = express();
const PORT = process.env.PORT || 3000;

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/myDatabase', { useNewUrlParser: true, useUnifiedTopology: true });
const db = mongoose.connection;

// Define Schema for the log object
const logSchema = new mongoose.Schema({
  operation: String,
  object: String,
  timestamp: { type: Date, default: Date.now }
});

// Create model based on schema
const Log = mongoose.model('Log', logSchema);

// Connect to Kafka
const kafka = new Kafka({
  clientId: 'logging-service',
  brokers: ['localhost:9092']
});

const producer = kafka.producer();

// Middleware to parse JSON requests
app.use(express.json());

// Routes for CRUD operations
app.post('/logs', async (req, res) => {
  try {
    const { operation, object } = req.body;

    // Save log to MongoDB
    const newLog = new Log({ operation, object });
    await newLog.save();

    // Send log message to Kafka
    await producer.send({
      topic: 'log-topic',
      messages: [{ value: JSON.stringify(newLog) }]
    });

    res.status(201).json({ message: 'Log created successfully', log: newLog });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create log' });
  }
});

// Start server
app.listen(PORT, async () => {
  console.log(`Server is running on port ${PORT}`);

  // Connect Kafka producer
  await producer.connect();
  console.log('Connected to Kafka producer');
});
```

In this modified version, we've added integration with Kafka. Whenever a POST request is made to `/logs`, the microservice will save the log to MongoDB as before, but it will also send the log message to Kafka.

The Kafka integration uses the `kafkajs` library to create a Kafka producer. When a log is created, it sends a message to the Kafka topic named `log-topic`. 

Ensure you have Kafka running on your system, and a topic named `log-topic` is created before running this code. You'll also need to install the `kafkajs` library (`npm install kafkajs`).

This setup allows your other microservices to produce log messages to Kafka, and it's Kafka's responsibility to deliver these messages to consumers, including the logging microservice, which will then persist the logs to MongoDB.

