It appears that you want to prepopulate the user's existing profile data in the form fields for updating their profile. You can do this by setting the `formData` state with the user's existing data when it's available. Here's how you can modify the `useEffect` to prepopulate the form:

```jsx
import React, { useState, useEffect } from "react";
import axios from "axios";
import { BACKEND_APPLICATION_BASE_URL } from "../../common/globalConstants";
import { getUserIdFromToken } from "../../common/authService";

function UpdateUserProfile() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    mobile: "",
  });

  const [user, setUser] = useState(null);

  useEffect(() => {
    // Fetch the user's profile data
