To create REST endpoints for creating, updating, getting all, and getting by ID for the given model structure in separate router modules, you can define the routes in the following way. We'll create separate router modules for each of these operations:

1. Create a Router for Handling Resumes:

```javascript
// resumeRoutes.js

const express = require('express');
const router = express.Router();
const Resume = require('../models/ResumeModel');

// Create a new resume
router.post('/', async (req, res) => {
  try {
    const newResume = new Resume(req.body);
    await newResume.save();
    res.status(201).json(newResume);
  } catch (error) {
    res.status(400).json({ error: 'Error creating resume' });
  }
});

// Update a resume by ID
router.put('/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const updatedResume = await Resume.findByIdAndUpdate(id, req.body, { new: true });
    if (!updatedResume) {
      return res.status(404).json({ error: 'Resume not found' });
    }
    res.json(updatedResume);
  } catch (error) {
    res.status(400).json({ error: 'Error updating resume' });
  }
});

// Get all resumes
router.get('/', async (req, res) => {
  try {
    const resumes = await Resume.find();
    res.json(resumes);
  } catch (error) {
    res.status(500).json({ error: 'Error fetching resumes' });
  }
});

// Get a resume by ID
router.get('/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const resume = await Resume.findById(id);
    if (!resume) {
      return res.status(404).json({ error: 'Resume not found' });
    }
    res.json(resume);
  } catch (error) {
    res.status(500).json({ error: 'Error fetching resume' });
  }
});

module.exports = router;
```

2. Create a Router for Handling Projects:

```javascript
// projectRoutes.js

const express = require('express');
const router = express.Router();
const Resume = require('../models/ResumeModel');

// Update a project by ID
router.put('/:resumeId/projects/:projectId', async (req, res) => {
  const { resumeId, projectId } = req.params;

  try {
    const resume = await Resume.findById(resumeId);
    if (!resume) {
      return res.status(404).json({ error: 'Resume not found' });
    }

    const project = resume.companies.id(projectId);
    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    project.set(req.body);
    await resume.save();
    res.json(project);
  } catch (error) {
    res.status(400).json({ error: 'Error updating project' });
  }
});

module.exports = router;
```

Please note that these routers assume you have a `ResumeModel` for your data model. You may need to customize them based on the actual structure of your models and the requirements of your application.

