import React from 'react';

const TaskList = ({ tasks, itemsPerRow = 3, onEditTask }) => {
  const containerStyle = {
    display: 'flex',
    flexWrap: 'wrap',
    justifyContent: 'space-between', // Adjust as needed
  };

  const taskItemStyle = {
    flex: '0 0 calc(33.33% - 10px)', // Default to 3 items per row with 10px spacing
    margin: '5px', // Adjust spacing between items as needed
    padding: '10px',
    border: '1px solid #ccc',
    boxSizing: 'border-box',
    backgroundColor: '#f0f0f0',
    /* Add any other styling you need */
  };

  const rows = [];
  for (let i = 0; i < tasks.length; i += itemsPerRow) {
    const rowTasks = tasks.slice(i, i + itemsPerRow);
    rows.push(
      <div style={containerStyle} key={i}>
        {rowTasks.map((task) => (
          <div style={taskItemStyle} key={task.id}>
            <strong>ID:</strong> {task.id}<br />
            <strong>Unique ID:</strong> {task.uniqueId}<br />
            <strong>Title:</strong> {task.title}<br />
            <strong>Description:</strong> {task.description}<br />
            <strong>Created Date:</strong> {task.createdDate}<br />
            <strong>Updated Date:</strong> {task.updatedDate}<br />
            <button onClick={() => onEditTask(task)}>Edit</button>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div>
      <h2>Task List</h2>
      {rows}
    </div>
  );
};

export default TaskList;

