```jsx
import React, { useState } from 'react';
import { BACKEND_APPLICATION_BASE_URL } from '../../common/globalConstants';
import { NavLink, useNavigate } from 'react-router-dom';

const inputStyle = {
  width: '100%',
  padding: '10px',
  border: '1px solid #ccc',
  borderRadius: '5px',
  fontSize: '16px',
};

const buttonStyle = {
  width: '100%',
  padding: '10px',
  backgroundColor: '#007bff',
  color: '#fff',
  border: 'none',
  borderRadius: '5px',
  fontSize: '16px',
  cursor: 'pointer',
};

const containerStyle = {
  maxWidth: '300px',
  margin: '0 auto',
  padding: '20px',
  border: '1px solid #ccc',
  borderRadius: '5px',
  backgroundColor: '#f5f5f5',
};

const labelStyle = {
  display: 'block',
  fontWeight: 'bold',
};

function Registration() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    confirmPassword: '', // Added confirm password field
  });

  const [passwordError, setPasswordError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    // Reset password error when the user makes changes
    setPasswordError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Check if passwords match
    if (formData.password !== formData.confirmPassword) {
      setPasswordError('Passwords do not match');
      return;
    }

    // Check if the password contains a capital letter and alphanumeric characters
    const passwordRegex = /^(?=.*[A-Z])(?=.*[0-9])[A-Za-z0-9]+$/;
    if (!passwordRegex.test(formData.password)) {
      setPasswordError('Password must contain a capital letter and alphanumeric characters');
      return;
    }

    try {
      const response = await fetch(`${BACKEND_APPLICATION_BASE_URL}/api/users/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.status === 201) {
        // Registration successful
        console.log('User registered successfully');
        // Redirect or show a success message
      } else {
        // Registration failed
        const data = await response.json();
        console.error('Registration error:', data.message);
        // Show an error message to the user
      }
