  });

  const [passwordError, setPasswordError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    // Reset password error when the user makes changes
    setPasswordError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Check if passwords match
    if (formData.password !== formData.confirmPassword) {
      setPasswordError('Passwords do not match');
      return;
    }

    // Check if the password contains a capital letter and alphanumeric characters
    const passwordRegex = /^(?=.*[A-Z])(?=.*\d)[A-Za-z\d]+$/;
    if (!passwordRegex.test(formData.password)) {
      setPasswordError('Password must contain a capital letter and alphanumeric characters');
      return;
    }

    try {
      const response = await fetch(`${BACKEND_APPLICATION_BASE_URL}/api/users/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.status === 201) {
        // Registration successful
        console.log('User registered successfully');
        // Redirect or show a success message
      } else {
        // Registration failed
        const data = await response.json();
        console.error('Registration error:', data.message);
        // Show an error message to the user
      }
    } catch (error) {
      console.error('Error registering user:', error);
    }
  };

  return (
    <div style={containerStyle}>
      <h2>Registration</h2>
      <form onSubmit={handleSubmit}>
        <div style={labelStyle}>
          <label htmlFor="username">Username:</label>
          <input
            type="text"
            id="username"
            name="username"
            value={formData.username}
            onChange={handleChange}
            required
            style={inputStyle}
          />
        </div>
        <div style={labelStyle}>
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            required
            style={inputStyle}
          />
        </div>
        <div style={labelStyle}>
          <label htmlFor="confirmPassword">Confirm Password:</label>
          <input
            type="password"
            id="confirmPassword"
            name="confirmPassword"
            value={formData.confirmPassword}
            onChange={handleChange}
            required
            style={inputStyle}
          />
        </div>
        {passwordError && (
          <div style={{ color: 'red' }}>{passwordError}</div>
        )}
        <button type="submit" style={buttonStyle}>
          Register
        </button>
        <div>
          {/* Link to the login page */}
          <p>
            Already have an account? <NavLink to="/login">Login</NavLink>
          </p>
        </div>
      </form>
    </div>
  );
}

export default Registration;
```

In this updated code, I replaced `[0-9]` with `\d` in the `passwordRegex` regular expression to match numeric characters. The regex now requires both a capital letter and at least one numeric character for a valid password.

