```

2. Create a new file for your login router, e.g., `loginRouter.js`. In this file, define the login-related routes and logic.

```javascript
// loginRouter.js
const express = require('express');
const router = express.Router();

// Route for displaying the login form (GET request)
router.get('/login', (req, res) => {
  res.render('login'); // You can replace 'login' with the name of your login page template
});

// Route for handling the login form submission (POST request)
router.post('/login', (req, res) => {
  const { username, password } = req.body;

  // Perform authentication logic here (e.g., check credentials against a database)
  // Replace the following with your actual authentication code
  if (username === 'your_username' && password === 'your_password') {
    // Successful login
    res.send('Login successful'); // You can customize this response as needed
  } else {
    // Failed login
    res.status(401).send('Login failed'); // You can customize this response as needed
  }
});

module.exports = router;
```

3. In your main Express application file (e.g., `app.js`), include the login router and set up the necessary middleware:

```javascript
// app.js
const express = require('express');
