Certainly! Below is a Node.js application that provides endpoints for user signup, login, and JWT token validation. We'll use Express, Mongoose, bcrypt for password hashing, and jsonwebtoken for JWT handling.

**1. Install dependencies**
```sh
npm init -y
npm install express mongoose bcrypt jsonwebtoken body-parser
```

**2. Create the application**

`index.js`:
```javascript
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());

mongoose.connect('mongodb://localhost:27017/auth_service', {
    useNewUrlParser: true,
    useUnifiedTopology: true
});

const userSchema = new mongoose.Schema({
    username: { type: String, unique: true },
    password: String
});

const User = mongoose.model('User', userSchema);

const secretKey = 'your_secret_key';  // Replace with a strong secret key

// Signup
app.post('/signup', async (req, res) => {
    const { username, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    try {
        const user = new User({ username, password: hashedPassword });
        await user.save();
        res.status(201).send({ message: 'User created successfully' });
    } catch (err) {
        res.status(400).send({ message: 'Error creating user', error: err.message });
    }
});

// Login
app.post('/login', async (req, res) => {
    const { username, password } = req.body;
    const user = await User.findOne({ username });
    if (!user) {
        return res.status(401).send({ message: 'Invalid username or password' });
    }
    const isPasswordValid = await bcrypt.compare(password, user.password);
    if (!isPasswordValid) {
        return res.status(401).send({ message: 'Invalid username or password' });
    }
    const token = jwt.sign({ userId: user._id }, secretKey, { expiresIn: '1h' });
    res.send({ token });
});

// Validate JWT
app.get('/validate', (req, res) => {
    const token = req.headers['authorization'];
    if (!token) {
        return res.status(401).send({ message: 'No token provided' });
    }
    jwt.verify(token, secretKey, (err, decoded) => {
        if (err) {
            return res.status(401).send({ message: 'Failed to authenticate token' });
        }
        res.send({ message: 'Token is valid', userId: decoded.userId });
    });
});

app.listen(3002, () => {
    console.log('Auth service listening on port 3002');
});
```

### Running the Application

1. Ensure MongoDB is running.
2. Start the application:
    ```sh
    node index.js
    ```

This application will listen on port 3002 and provide endpoints for signing up (`/signup`), logging in (`/login`), and validating JWT tokens (`/validate`). Replace `your_secret_key` with a strong secret key for JWT signing.

