```javascript
const fs = require('fs');
const readline = require('readline');

function processFile(inputFilePath, outputFilePath) {
    const inputReadStream = fs.createReadStream(inputFilePath, 'utf8');
    const outputWriteStream = fs.createWriteStream(outputFilePath, { flags: 'a' });

    const rl = readline.createInterface({
        input: inputReadStream,
        crlfDelay: Infinity,
    });

    rl.on('line', (line) => {
        // Check if the line starts with "**" and ends with "**"
        if (line.startsWith('**') && line.endsWith('**')) {
            // Remove "*" symbols and write the modified line to the output file
            const modifiedLine = line.slice(2, -2).trim();
            outputWriteStream.write(`${modifiedLine}\n`);
        }
    });

    rl.on('close', () => {
        console.log('Processing completed. Results written to', outputFilePath);
        inputReadStream.close();
        outputWriteStream.close();
    });
}

